/* vNN.xx, UI REDESIGN ui5q2c (his #50, from the AAA judge of the title shot with the second window blocked): NOTHING JUMPS. The
   alert card (the blocked second window and RETRY) was put into the column between the mode rows and the saves, so the whole
   title, name, cards and rows, jumped up about 37px under the mouse or the pad the moment it came up. On a wide screen it is a
   callout beside the mode rows now, level with the second row, and nothing else moves. A narrow screen keeps it in the column. */
@media (min-aspect-ratio: 7/5) and (min-width: 1500px){
  #root #modemenu{ position:relative; }
  #root #modealert{ position:absolute; left:calc(50% + 296px); top:68px; width:420px; z-index:2; margin:0; flex-direction:column;
    align-items:stretch; gap:12px; padding:14px 16px 14px 18px; box-shadow:0 14px 36px rgba(0,0,0,.55); }
  #root #modemenu #moderetry{ width:100%; }
}
/* vNN.xx, UI REDESIGN ui5q1c (his #50, from the AAA judge

check:
{v:'VER',what:'his #50 (UI redesign ui5q2c): when the blocked-window alert card comes up on the title, the saves below the mode rows do not move (on a wide screen the card is a callout beside the rows)',
 run:function(){
   var ti=document.getElementById('title'), al=document.getElementById('modealert'), msg=document.getElementById('modemsg'),
       rt=document.getElementById('moderetry'), sp=document.getElementById('slotpanel');
   if(!ti||!al||!msg||!rt||!sp) return 'SKIP: no alert card on this title';
   var was=ti.classList.contains('on'), s0=[al.style.display,msg.style.display,rt.style.display,msg.textContent], y0, y1;
   var wide=window.matchMedia('(min-aspect-ratio: 7/5) and (min-width: 1500px)').matches;
   try{
     if(!was) ti.classList.add('on');
     y0=sp.getBoundingClientRect().top;
     al.style.display=''; msg.style.display=''; rt.style.display=''; msg.textContent='The browser blocked the second window. Allow popups for this page, then press RETRY.';
     y1=sp.getBoundingClientRect().top;
     if(wide){ if(Math.abs(y1-y0)>1) return 'the saves moved '+Math.round(y1-y0)+'px when the alert card came up'; return null; }
     var css=[].slice.call(document.querySelectorAll('style')).map(function(s){ return s.textContent; }).join('');
     return css.indexOf('#modealert{ position:'+'absolute')>=0?null:'the alert card is in the column flow';
   } finally {
     al.style.display=s0[0]; msg.style.display=s0[1]; rt.style.display=s0[2]; msg.textContent=s0[3];
     if(!was) ti.classList.remove('on');
   } }},
